# Fields: the open ground, cut into farm-sized parcels so each takes its own furrows. Inside the Park Service map the
# woods are its wartime woods; outside it they are guessed: steep banks, the bottoms along Bull Run and Cub Run, the
# "Big Forest" the flank march went through, and some woodlots by chance.
WOODS = [[M(*p) for p in poly] for poly in WOODS_LL]; COVER = [M(*p) for p in MAP_COVER_LL]
BIG_FOREST = [M(*p) for p in [(38.8341, -77.4980), (38.8320, -77.4720), (38.8420, -77.4660), (38.8530, -77.4800), (38.8560, -77.5050), (38.8460, -77.5100)]]
def inside(x, y, poly):
    c = False
    for i in range(len(poly)):
        (xa, ya), (xb, yb) = poly[i], poly[i - 1]
        if (ya > y) != (yb > y) and x < xa + (xb - xa) * (y - ya) / (yb - ya): c = not c
    return c
def near(x, y, line, d):
    for (xa, ya), (xb, yb) in zip(line, line[1:]):
        dx, dy = xb - xa, yb - ya; t = max(0, min(1, ((x - xa) * dx + (y - ya) * dy) / (dx * dx + dy * dy or 1)))
        if math.hypot(x - xa - t * dx, y - ya - t * dy) < d: return True
    return False
def hashf(i, j, s=0): return ((i * 73856093 ^ j * 19349663 ^ s * 83492791) & 0xffff) / 0xffff
def noise(x, y, cell=500):
    i, j = math.floor(x / cell), math.floor(y / cell); u, v = x / cell - i, y / cell - j
    a, b, c, d = hashf(i, j), hashf(i + 1, j), hashf(i, j + 1), hashf(i + 1, j + 1)
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
CELL, PARCEL = 50, 900
def wooded(x, y):
    if inside(x, y, COVER): return any(inside(x, y, w) for w in WOODS)
    slope = math.hypot(z(x + 40, y) - z(x - 40, y), z(x, y + 40) - z(x, y - 40)) / 80
    return inside(x, y, BIG_FOREST) or near(x, y, L['bull_run'], 90) or near(x, y, L['cub_run'], 70) or slope + 0.25 * noise(x, y) > 0.2
SEEDS = [(gx * PARCEL + (hashf(gx, gy, 1) - 0.5) * PARCEL * 0.8, gy * PARCEL + (hashf(gx, gy, 2) - 0.5) * PARCEL * 0.8) for gx in range(-10, 11) for gy in range(-10, 11)]
def parcel(x, y):
    gx, gy = round(x / PARCEL), round(y / PARCEL)
    return min(((i, j) for i in range(gx - 2, gx + 3) for j in range(gy - 2, gy + 3) if -10 <= i <= 10 and -10 <= j <= 10),
               key=lambda k: math.hypot(SEEDS[(k[0] + 10) * 21 + k[1] + 10][0] - x, SEEDS[(k[0] + 10) * 21 + k[1] + 10][1] - y))
N = 11000 // CELL
cells = {}
for j in range(N):
    for i in range(N):
        x, y = -5500 + (i + 0.5) * CELL, -5500 + (j + 0.5) * CELL
        if not wooded(x, y): cells.setdefault(parcel(x, y), set()).add((i, j))
def area(r): return sum(r[i][0] * r[(i + 1) % len(r)][1] - r[(i + 1) % len(r)][0] * r[i][1] for i in range(len(r))) / 2
def dp(pts, tol):
    if len(pts) < 3: return pts
    (x0, y0), (x1, y1) = pts[0], pts[-1]; Ln = math.hypot(x1 - x0, y1 - y0) or 1
    dist = [abs((x1 - x0) * (y0 - y) - (x0 - x) * (y1 - y0)) / Ln for x, y in pts]
    k = max(range(len(pts)), key=dist.__getitem__)
    return [pts[0], pts[-1]] if dist[k] <= tol else dp(pts[:k + 1], tol)[:-1] + dp(pts[k:], tol)
def rings(S):  # boundary edges with the open cell on the left, linked into loops: outer rings run anticlockwise, holes clockwise
    E = {}
    for i, j in S:
        for (di, dj), e0, e1 in (((0, -1), (i, j), (i + 1, j)), ((1, 0), (i + 1, j), (i + 1, j + 1)), ((0, 1), (i + 1, j + 1), (i, j + 1)), ((-1, 0), (i, j + 1), (i, j))):
            if (i + di, j + dj) not in S: E.setdefault(e0, []).append(e1)
    out = []
    while E:
        s = next(iter(E)); ring = [s]; p = s
        while True:
            q = E[p].pop()
            if not E[p]: del E[p]
            if q == s: break
            ring.append(q); p = q
        r = [(-5500 + u * CELL, -5500 + v * CELL) for u, v in ring]
        k = max(range(len(r)), key=lambda n: math.hypot(r[n][0] - r[0][0], r[n][1] - r[0][1]))
        out.append(dp(r[:k + 1], 40)[:-1] + dp(r[k:] + [r[0]], 40)[:-1])
    return out
FIELDS = []
for key in sorted(cells):
    rs = rings(cells[key]); outer = [r for r in rs if area(r) > 40000]
    for o in outer:
        for hole in (r for r in rs if area(r) < -20000 and inside(*r[0], o)):  # bridged in, so even-odd and non-zero fills both leave it out
            k = min(range(len(o)), key=lambda n: math.hypot(o[n][0] - hole[0][0], o[n][1] - hole[0][1]))
            o[:] = o[:k + 1] + hole + [hole[0]] + o[k:]
        FIELDS.append([(round(x), round(y)) for x, y in o])

